referenceSolutions.javascript:
export function uniquePaths(rows        , columns        )         {
const dp         =Array(columns).fill(1);for(let r=1;r<rows;r++)for(let c=1;c<columns;c++)dp[c]+=dp[c-1];return dp[columns-1];
}

